void sync_count_update( Sync_Count_Obj sync , Sync_Count new_count )
{
    TRACE_DEI_SYNC("\n\r[LIB.SYNC_COUNT] 0x%08X UPDATE current_count = %d \n\r", sync , new_count );  

    sync->current_count = new_count ; 
}

